import { CarPrices, SeoRoute } from '../models/catalog.model';
import routesJson from './seo-routes.json';

/**
 * EVERY Chhattisgarh/Nagpur route in the price list, most booked first — each has its own
 * page at /taxi/<from>-to-<to> (generated by scripts/build-catalog.py).
 *
 * This file is only imported by route, routes-index and city pages (lazy chunks). Home,
 * footer and service pages use the small `popular-routes` list instead.
 */
type Row = [from: string, to: string, km: number, hatchback: number, sedan: number, suv: number];

/** 'Nagpur (MH)' → 'Nagpur' (same rule as the build script). */
export const displayName = (key: string) => key.replace(/\s*\([A-Z]{2}\)$/, '');
export const slugify = (text: string) =>
  text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');

function toRoute([from, to, km, h, s, suv]: Row): SeoRoute {
  const fromName = displayName(from);
  const toName = displayName(to);
  const fares: CarPrices = { Hatchback: h, Sedan: s, SUV: suv };
  return { slug: `${slugify(fromName)}-to-${slugify(toName)}`, from, to, fromName, toName, km, fares };
}

export const SEO_ROUTES: readonly SeoRoute[] = (routesJson as Row[]).map(toRoute);
export const SEO_ROUTE_BY_SLUG = new Map(SEO_ROUTES.map((r) => [r.slug, r]));

export { routePath } from './popular-routes';

/** Routes starting or ending at a place (by fare-data key), most booked first. */
export function routesFor(placeKey: string, limit = 12): SeoRoute[] {
  return SEO_ROUTES.filter((r) => r.from === placeKey || r.to === placeKey).slice(0, limit);
}

/** Routes starting at a place, most booked first. */
export function routesFrom(placeKey: string): SeoRoute[] {
  return SEO_ROUTES.filter((r) => r.from === placeKey);
}

export function reverseOf(route: SeoRoute): SeoRoute | undefined {
  return SEO_ROUTES.find((r) => r.from === route.to && r.to === route.from);
}

/** Other pages to link from a route page: the return trip first, then routes sharing a city. */
export function relatedRoutes(route: SeoRoute, limit = 9): SeoRoute[] {
  const reverse = reverseOf(route);
  const others = SEO_ROUTES.filter(
    (r) => r !== route && r !== reverse && (r.from === route.from || r.to === route.to || r.from === route.to),
  );
  return [...(reverse ? [reverse] : []), ...others].slice(0, limit);
}
